param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$Runtime,[Parameter(Mandatory=$true)][string]$NativeDirectory,[Parameter(Mandatory=$true)][string]$OutputDirectory,[switch]$ResultsOnly)
$ErrorActionPreference='Stop';$exe=(Resolve-Path $Executable).Path;if(!$ResultsOnly){if(Test-Path $OutputDirectory){throw 'Fresh contrast outputs required'};New-Item -ItemType Directory $OutputDirectory|Out-Null};$out=(Resolve-Path $OutputDirectory).Path;$cases=Get-Content "$NativeDirectory/cases.json" -Raw|ConvertFrom-Json;$records=@()
foreach($case in $cases){foreach($shape in @('h80_w96','h96_w80')){$tag="$($case.name)_$shape";if(!$ResultsOnly){$ErrorActionPreference='Continue';& $exe "$NativeDirectory/$($case.name)/$shape" $Runtime "$out/api_$tag" *> "$out/api_$tag.log";$code=$LASTEXITCODE;$ErrorActionPreference='Stop';if($code -ne 0){throw "Contrast failure:$tag"}}
 if(!(Test-Path "$out/api_$tag/PASS.txt")){throw "Missing contrast PASS:$tag"};if((Get-Content "$out/api_$tag.log" -Raw) -match 'VUID-|Validation Error|\[ERROR\]'){throw 'Vulkan errors'};$rows=@(Import-Csv "$out/api_$tag/results.tsv" -Delimiter "`t");if($rows.Count -ne 69){throw 'Incomplete stages'};$n=0;foreach($row in $rows){if([int]$row.numeric_errors -ne 0 -or [int]$row.bit_errors -ne 0){throw 'Strict parity failure'};$n+=[int]$row.values};if($n -ne 237733){throw "Incomplete values:$n"};$s=Get-Content "$out/api_$tag/scores.json" -Raw|ConvertFrom-Json;$records+=[pscustomobject]@{case=$tag;pattern=$case.pattern;transform=$case.transform;gain=$case.gain;offset=0;level=$(if($case.level){$case.level}else{10});stages=69;values=$n;bit_errors=0;Q=$s.Q;Q_JOD=$s.Q_JOD}
}}
if($records.Count -ne 2*$cases.Count){throw 'Incomplete case/orientation coverage'};$records|ConvertTo-Json|Set-Content "$out/results.json";Get-FileHash -LiteralPath $exe,$PSCommandPath,"$Runtime/pathway.runtime","$NativeDirectory/cases.json"|Select-Object Path,Hash|ConvertTo-Json|Set-Content "$out/hashes.json";Set-Content "$out/PASS.txt" "$($records.Count) contrast/luminance pairs:$($records.Count*69) stage checks/$($records.Count*237733) values bitwise exact;native P/log/bands/masks/D/errors/baseNoise/Q;no Vulkan errors."
